INSERT INTO majors (id, slug, code, name, group_id, summary, description, demand, growth, hidden, is_custom) VALUES
  ('giao-duc-chinh-tri', 'giao-duc-chinh-tri', 'GIAO-DUC-C', 'Giáo dục Chính trị', 'giao-duc', 'Chương trình đào tạo ngành Giáo dục Chính trị cung cấp kiến thức chuyên sâu và kỹ năng thực hành nghề nghiệp.', 'Ngành Giáo dục Chính trị trang bị hệ thống kiến thức toàn diện, đáp ứng nhu cầu tuyển dụng trong nước và quốc tế.', 'Cao', 12, false, false),
  ('bao-ve-thuc-vat', 'bao-ve-thuc-vat', 'BAO-VE-THU', 'Bảo vệ thực vật', 'xa-hoi', 'Chương trình đào tạo ngành Bảo vệ thực vật cung cấp kiến thức chuyên sâu và kỹ năng thực hành nghề nghiệp.', 'Ngành Bảo vệ thực vật trang bị hệ thống kiến thức toàn diện, đáp ứng nhu cầu tuyển dụng trong nước và quốc tế.', 'Cao', 12, false, false),
  ('su-pham-lich-su', 'su-pham-lich-su', 'SU-PHAM-LI', 'Sư phạm Lịch sử', 'giao-duc', 'Chương trình đào tạo ngành Sư phạm Lịch sử cung cấp kiến thức chuyên sâu và kỹ năng thực hành nghề nghiệp.', 'Ngành Sư phạm Lịch sử trang bị hệ thống kiến thức toàn diện, đáp ứng nhu cầu tuyển dụng trong nước và quốc tế.', 'Cao', 12, false, false),
  ('su-pham-ngu-van', 'su-pham-ngu-van', 'SU-PHAM-NG', 'Sư phạm Ngữ văn', 'giao-duc', 'Chương trình đào tạo ngành Sư phạm Ngữ văn cung cấp kiến thức chuyên sâu và kỹ năng thực hành nghề nghiệp.', 'Ngành Sư phạm Ngữ văn trang bị hệ thống kiến thức toàn diện, đáp ứng nhu cầu tuyển dụng trong nước và quốc tế.', 'Cao', 12, false, false),
