INSERT INTO school_reviews (id, school_id, user_id, author_name, anonymous, relation, cohort, major_id, rating_teaching, rating_facilities, rating_activities, rating_career, title, content, status, reject_reason, school_email, is_demo, created_at, updated_at, moderated_at, moderated_by) VALUES
  ('r-demo-01', 'hust', NULL, 'Minh T.', false, 'sinh-vien', 2022, 'cong-nghe-thong-tin', 5, 4, 4, 5, 'Nền tảng kỹ thuật vững, áp lực học khá cao', 'Chương trình nặng về toán và lập trình nền tảng nên hai năm đầu khá vất vả. Bù lại, đồ án môn học nhiều giúp mình quen làm việc nhóm. Phòng lab mở cửa đến tối, câu lạc bộ học thuật hoạt động đều. Nên chuẩn bị tốt Toán và tiếng Anh trước khi nhập học.', 'approved', NULL, false, true, '2026-06-12T08:00:00.000Z', '2026-06-12T08:00:00.000Z', '2026-06-13T02:00:00.000Z', 'u-000'),
  ('r-demo-02', 'hust', NULL, 'Ẩn danh', true, 'cuu-sinh-vien', 2018, 'ky-thuat-dien', 4, 3, 4, 5, 'Doanh nghiệp tuyển dụng nhiều, cơ sở vật chất một số khu đã cũ', 'Ra trường mình được giới thiệu thực tập qua các ngày hội việc làm của trường. Giảng viên chuyên ngành có kinh nghiệm thực tế. Một số giảng đường và phòng thí nghiệm cũ, mùa hè hơi nóng. Nhìn chung đáng để theo học nếu thích kỹ thuật.', 'approved', NULL, false, true, '2026-05-02T08:00:00.000Z', '2026-05-02T08:00:00.000Z', '2026-05-03T02:00:00.000Z', 'u-000'),
  ('r-demo-03', 'neu', NULL, 'Lan P.', false, 'sinh-vien', 2023, 'marketing', 4, 5, 5, 4, 'Hoạt động ngoại khoá sôi nổi, nhiều cơ hội thực tập', 'Khuôn viên hiện đại, thư viện rộng. Các câu lạc bộ chuyên ngành tổ chức cuộc thi thường xuyên nên có nhiều dịp làm dự án thật. Một vài học phần đại cương đông sinh viên nên ít tương tác. Nên chủ động tìm thực tập từ năm hai.', 'approved', NULL, false, true, '2026-07-20T08:00:00.000Z', '2026-07-20T08:00:00.000Z', '2026-07-21T02:00:00.000Z', 'u-000'),
  ('r-demo-04', 'ueh', NULL, 'Quân N.', false, 'cuu-sinh-vien', 2020, 'tai-chinh-ngan-hang', 4, 4, 4, 5, 'Mạng lưới cựu sinh viên mạnh, dễ kết nối ngân hàng', 'Trường có nhiều chương trình liên kết với ngân hàng và công ty tài chính nên việc tìm thực tập khá thuận lợi. Nội dung học cập nhật, có học phần phân tích dữ liệu. Cần tự học thêm chứng chỉ chuyên môn nếu muốn làm đầu tư.', 'approved', NULL, false, true, '2026-04-10T08:00:00.000Z', '2026-04-10T08:00:00.000Z', '2026-04-11T02:00:00.000Z', 'u-000'),
  ('r-demo-05', 'ueh', NULL, 'Thảo V.', false, 'sinh-vien', 2024, 'marketing', 5, 4, 5, 4, 'Giảng viên trẻ, học theo dự án', 'Nhiều môn chấm điểm qua dự án nhóm với doanh nghiệp, học thực tế và vui. Lịch học có lúc dồn vào cuối tuần. Cơ sở ở trung tâm nên đi lại hơi kẹt xe giờ cao điểm.', 'approved', NULL, false, true, '2026-08-02T08:00:00.000Z', '2026-08-02T08:00:00.000Z', '2026-08-03T02:00:00.000Z', 'u-000'),
  ('r-demo-06', 'fpt', NULL, 'Huy Đ.', false, 'sinh-vien', 2023, 'ky-thuat-phan-mem', 4, 5, 4, 5, 'Học kỳ doanh nghiệp rất đáng giá', 'Chương trình có học kỳ thực tập tại doanh nghiệp nên ra trường đã có kinh nghiệm. Học phí cao hơn trường công, cần cân nhắc tài chính. Cơ sở vật chất mới, nhiều không gian tự học.', 'pending', NULL, false, true, '2026-09-25T08:00:00.000Z', '2026-09-25T08:00:00.000Z', NULL, NULL),
  ('r-demo-07', 'neu', NULL, 'Khách', false, 'sinh-vien', 2025, NULL, 3, 3, 3, 3, 'Ai cần tài liệu ôn thi inbox mình', 'Mình có bộ tài liệu ôn thi đầy đủ các môn, bạn nào cần liên hệ số 0912 345 678 hoặc vào trang abc-tailieu.com để mua giá rẻ nhé. Trường học cũng được, không có gì đặc biệt để nói thêm.', 'pending', NULL, false, true, '2026-09-27T08:00:00.000Z', '2026-09-27T08:00:00.000Z', NULL, NULL);
